import{_ as e,c as a,o as i,ae as n}from"./chunks/framework.2MVDia4S.js";const p=JSON.parse('{"title":"Execution-client compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility.md","filePath":"compatibility.md"}'),o={name:"compatibility.md"};function r(d,t,c,l,s,u){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="execution-client-compatibility" tabindex="-1">Execution-client compatibility <a class="header-anchor" href="#execution-client-compatibility" aria-label="Permalink to &quot;Execution-client compatibility&quot;">​</a></h1><p>EthBFT compatibility is capability- and test-based, not brand-based. A client must expose authenticated chain/block/sync RPCs, capability exchange, and the configured Engine API method profile with specification-conforming payload serialization and status behavior.</p><h2 id="current-matrix" tabindex="-1">Current matrix <a class="header-anchor" href="#current-matrix" aria-label="Permalink to &quot;Current matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Client</th><th>Build/validation evidence</th><th>Status</th></tr></thead><tbody><tr><td>Geth</td><td>Bundled Shanghai single-validator Docker E2E</td><td>Reference integration</td></tr><tr><td>Reth</td><td>Not yet in continuous CI</td><td>Candidate</td></tr><tr><td>Nethermind</td><td>Not yet in continuous CI</td><td>Candidate</td></tr><tr><td>Besu</td><td>Not yet in continuous CI</td><td>Candidate</td></tr><tr><td>Erigon</td><td>Not yet in continuous CI</td><td>Candidate</td></tr></tbody></table><p>“Candidate” does not mean unsupported by design; it means the project has not yet earned a release-level compatibility claim.</p><h2 id="graduation-rule" tabindex="-1">Graduation rule <a class="header-anchor" href="#graduation-rule" aria-label="Permalink to &quot;Graduation rule&quot;">​</a></h2><p>A client/fork pair becomes supported only after capability negotiation, payload build/validation, transaction inclusion, restart recovery, malformed proposal rejection, and fork-boundary cases pass in continuous CI. Version ranges and known deviations must be recorded here before release.</p><p>Hive Engine API suites should be the external conformance baseline. EthBFT&#39;s mixed-client network tests must additionally cover the BFT lifecycle and crash boundaries that Engine API conformance alone cannot cover.</p>',8)])])}const m=e(o,[["render",r]]);export{p as __pageData,m as default};
